  --foreground: hsl(47.97 22.73% 19.33%);
  --card: hsl(47.95 50.03% 96.36%);
  --card-foreground: hsl(330 0% 7.73%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(50.77 19.5% 13.37%);
  --primary: hsl(15.13 56.98% 52.62%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(46.18 16.2% 88.6%);
  --secondary-foreground: hsl(50.71 9.79% 29.43%);
  --muted: hsl(43.98 35.12% 89.03%);
  --muted-foreground: hsl(49.95 3.17% 50.43%);
  --accent: hsl(46.18 16.2% 88.6%);
  --accent-foreground: hsl(50.77 19.5% 13.37%);
  --destructive: hsl(330 0% 7.73%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(49.95 10.33% 83.39%);
  --input: hsl(50.7 10.06% 67.33%);
  --ring: hsl(209.63 78.55% 48.81%);
  --chart-1: hsl(18.36 58.35% 43.96%);
  --chart-2: hsl(251.53 86.2% 74.67%);
  --chart-3: hsl(46.14 29.97% 81.52%);
  --chart-4: hsl(256.55 47.43% 88.12%);
  --chart-5: hsl(17.61 57.23% 44.35%);
